// Palette bar: now playing (ROADMAP 20), run by nowplaying.sh through osascript.
//   feed <sketchybar> <state file> <width> <scroll 1|0> <beat lines>   once a second; sets the item on change
// Since macOS 15.4 only Apple-signed programs may read MediaRemote; osascript is one (as in the Widgets app).
// Its commands are ignored, though: play/pause goes through perl and Palette's library (nowplaying.sh).
// (generated by Palette; edits are replaced when the bar settings change)
function run(argv) {
  ObjC.import('Foundation');
  $.NSBundle.bundleWithPath('/System/Library/PrivateFrameworks/MediaRemote.framework/').load;
  const [, sb, state, width, scroll, beats] = argv;
  const W = Math.max(parseInt(width, 10) || 24, 6);
  const SCROLL = scroll === '1';
  const BEATS = parseInt(beats, 10) || 0;
  const PLAYING = '', PAUSED = ''; // music note, pause
  const R = $.NSClassFromString('MRNowPlayingRequest');
  const set = (args) => {
    const t = $.NSTask.alloc.init;
    t.launchPath = sb;
    t.arguments = args;
    t.launch;
    t.waitUntilExit;
    return t.terminationStatus === 0;
  };
  const write = (text) => $(text).writeToFileAtomicallyEncodingError(state, true, $.NSUTF8StringEncoding, null);
  const beatsDrawing = (on) => (BEATS ? ['--set', '/beat\\..*/', `drawing=${on ? 'on' : 'off'}`] : []);
  let last = null;
  let sent = 0;
  while (true) {
    let o = null;
    if (R && !R.isNil()) {
      const item = R.localNowPlayingItem;
      const info = item.isNil() ? null : item.nowPlayingInfo;
      if (info && !info.isNil()) {
        const v = (k) => { const x = info.valueForKey('kMRMediaRemoteNowPlayingInfo' + k); return x.isNil() ? null : ObjC.unwrap(x); };
        const p = R.localNowPlayingPlayerPath;
        o = { title: v('Title'), artist: v('Artist'), playing: !!R.localIsPlaying,
              app: (p && !p.isNil() && !p.client.isNil()) ? ObjC.unwrap(p.client.bundleIdentifier) : '' };
      }
    }
    const key = JSON.stringify(o);
    // On a change, and every 15 s anyway: a bar reload brings the items back hidden.
    if (key !== last || Date.now() - sent > 15000) {
      last = key;
      sent = Date.now();
      let args;
      if (!o || !o.title) {
        args = ['--set', 'nowplaying', 'drawing=off', ...beatsDrawing(false)];
        write('none\n');
      } else {
        let text = o.artist ? `${o.title} – ${o.artist}` : o.title;
        const chars = [...text];
        if (!SCROLL && chars.length > W) text = chars.slice(0, W - 1).join('').trimEnd() + '…';
        args = ['--set', 'nowplaying', 'drawing=on', `label=${text}`, `icon=${o.playing ? PLAYING : PAUSED}`, ...beatsDrawing(true)];
        write(`${o.playing ? 'playing' : 'paused'}\n${o.app || ''}\n`);
      }
      if (!set(args)) return; // SketchyBar quit or reloaded, or the item is gone: nowplaying.sh starts a new one
    }
    delay(1);
  }
}
